function cronListBlock(id: string, name: string, state: "active" | "paused", lastRun?: string): string {
  return `  ${id} [${state}]\n    Name:      ${name}\n    Last run:  ${lastRun ?? "never"}\n`;
}

function fakeHermes(
  home: string,
