  },
  async run({ args }) {
    const slug = String(args.slug ?? "").trim();
    if (!slug) {
      guidedError({
        context: "dora harness open needs a routine slug",
        problem: "Missing slug",
        solutions: ["Pass the slug from `dora harness list`."],
