function liveJobId(home: string, slug: string): string | undefined {
  const routine = readRoutine(home, slug);
  const jobs = listCronJobs();
  if (routine.jobId) {
    if (jobs && !jobs.some((j) => j.id === routine.jobId)) return undefined;
